class AdminUsersScreen extends StatefulWidget{const AdminUsersScreen({super.key,this.repository});final SuperAdminRepository? repository;@override State<AdminUsersScreen> createState()=>_S();}class _S extends State<AdminUsersScreen>{late final repo=widget.repository??SuperAdminRepository();String? status,role;String search='';late Future<AdminPage<AdminUserModel>> f=_load();Future<AdminPage<AdminUserModel>> _load()=>repo.getUsers(search:search,status:status,role:role);void _refresh()=>setState(()=>f=_load());@override Widget build(BuildContext c)=>Column(children:[Padding(padding:const EdgeInsets.all(12),child:TextField(decoration:const InputDecoration(labelText:'Search users'),onSubmitted:(v){search=v;_refresh();})),Wrap(spacing:8,children:[for(final s in [null,'ACTIVE','INACTIVE','SUSPENDED'])FilterChip(label:Text(s??'ALL'),selected:status==s,onSelected:(_){status=s;_refresh();}),DropdownButton<String?>(value:role,hint:const Text('Role'),items:[null,'SUPER_ADMIN','MASJID_ADMIN','IMAM','COMMITTEE_MEMBER','MEMBER'].map((r)=>DropdownMenuItem(value:r,child:Text(r??'All roles'))).toList(),onChanged:(v){role=v;_refresh();})]),Expanded(child:FutureBuilder(future:f,builder:(c,s){if(s.connectionState!=ConnectionState.done)return const LoadingView();if(s.hasError)return ErrorView(title:'Unable to load',message:s.error.toString(),onRetry:_refresh);final items=s.data?.items??[];return RefreshIndicator(onRefresh:()async=>_refresh(),child:ListView(children:[for(final item in items)AdminUserCard(item:item,onStatus:()async{final st=await showUpdateUserStatusDialog(c);if(st!=null){await repo.updateUserStatus(item.id,st);_refresh();}}),if(items.isEmpty)const Padding(padding:EdgeInsets.all(32),child:Center(child:Text('No users found')))]));}))]);}
